
// Bowyer-Watson 
export	class DelaunayTriangulation {
	private triangles = []
	constructor() {
		this.triangles = [];
	}
	private orientation(a, b, c) {
		return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
	}
	private isPointInCircumcircle(point, triangle) {
		const [a, b, c] = triangle;
		
		const orient = this.orientation(a, b, c);
		if (orient === 0) return false;
		
		let [p1, p2, p3] = [a, b, c];
		if (orient < 0) {
			[p2, p3] = [p3, p2];
		}
		
		const ax = p1.x - point.x;
		const ay = p1.y - point.y;
		const bx = p2.x - point.x;
		const by = p2.y - point.y;
		const cx = p3.x - point.x;
		const cy = p3.y - point.y;
		
		const det = (ax * ax + ay * ay) * (bx * cy - by * cx) -
					(bx * bx + by * by) * (ax * cy - ay * cx) +
					(cx * cx + cy * cy) * (ax * by - ay * bx);
					
		return det > 0;
	}
	private pointsEqual(p1, p2) {
		return Math.abs(p1.x - p2.x) < 1e-10 && Math.abs(p1.y - p2.y) < 1e-10;
	}
	private edgesEqual(e1, e2) {
		return (this.pointsEqual(e1[0], e2[0]) && this.pointsEqual(e1[1], e2[1])) ||
				(this.pointsEqual(e1[0], e2[1]) && this.pointsEqual(e1[1], e2[0]));
	}
	private containsSuperTrianglePoint(triangle, superTriangle) {
		return triangle.some(p => superTriangle.some(sp => this.pointsEqual(p, sp)));
	}
	private getCircumcenter(triangle) {
		const [a, b, c] = triangle;
		
		const d = 2 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
		if (Math.abs(d) < 1e-10) return null;
		
		const ux = ((a.x * a.x + a.y * a.y) * (b.y - c.y) +
					(b.x * b.x + b.y * b.y) * (c.y - a.y) +
					(c.x * c.x + c.y * c.y) * (a.y - b.y)) / d;
					
		const uy = ((a.x * a.x + a.y * a.y) * (c.x - b.x) +
					(b.x * b.x + b.y * b.y) * (a.x - c.x) +
					(c.x * c.x + c.y * c.y) * (b.x - a.x)) / d;
					
		return { x: ux, y: uy };
	}
	

	public triangulate(points) {
		if (points.length < 3) return [];

		const uniquePoints = [];
		for (const point of points) {
			if (!uniquePoints.some(p => this.pointsEqual(p, point))) {
				uniquePoints.push(point);
			}
		}
		
		if (uniquePoints.length < 3) return [];
		
		const minX = Math.min(...uniquePoints.map(p => p.x));
		const maxX = Math.max(...uniquePoints.map(p => p.x));
		const minY = Math.min(...uniquePoints.map(p => p.y));
		const maxY = Math.max(...uniquePoints.map(p => p.y));
		
		const dx = maxX - minX;
		const dy = maxY - minY;
		const deltaMax = Math.max(dx, dy);
		const midx = (minX + maxX) / 2;
		const midy = (minY + maxY) / 2;
		
		const superTriangle = [
			{ x: midx - 20 * deltaMax, y: midy - deltaMax },
			{ x: midx, y: midy + 20 * deltaMax },
			{ x: midx + 20 * deltaMax, y: midy - deltaMax }
		];
		
		let triangles = [superTriangle];
		
		// Bowyer-Watson
		for (const point of uniquePoints) {
			const badTriangles = [];
			
			for (const triangle of triangles) {
				if (this.isPointInCircumcircle(point, triangle)) {
					badTriangles.push(triangle);
				}
			}
			
			if (badTriangles.length === 0) continue;
			
			const edges = [];
			for (const triangle of badTriangles) {
				edges.push(
					[triangle[0], triangle[1]],
					[triangle[1], triangle[2]],
					[triangle[2], triangle[0]]
				);
			}
			
			const boundaryEdges = [];
			for (let i = 0; i < edges.length; i++) {
				let isDuplicate = false;
				for (let j = 0; j < edges.length; j++) {
					if (i !== j && this.edgesEqual(edges[i], edges[j])) {
						isDuplicate = true;
						break;
					}
				}
				if (!isDuplicate) {
					boundaryEdges.push(edges[i]);
				}
			}
			
			triangles = triangles.filter(triangle => !badTriangles.includes(triangle));
			
			for (const edge of boundaryEdges) {
				const newTriangle = [edge[0], edge[1], point];
				const area = Math.abs(this.orientation(newTriangle[0], newTriangle[1], newTriangle[2]));
				if (area > 1e-10) {
					triangles.push(newTriangle);
				}
			}
		}
		
		const finalTriangles = triangles.filter(triangle => 
			!this.containsSuperTrianglePoint(triangle, superTriangle)
		);
		
		this.triangles = finalTriangles;
		return finalTriangles;
	}
	public computeVoronoi(points) {
		const triangles = this.triangulate(points);
		if (triangles.length === 0) return [];
		
		const voronoiCells = new Map();
		
		for (const point of points) {
			voronoiCells.set(point, []);
		}
		
		for (const triangle of triangles) {
			const center = this.getCircumcenter(triangle);
			if (!center) continue;
			
			for (const vertex of triangle) {
				const cell = voronoiCells.get(vertex);
				if (cell) {
					cell.push({ center, triangle });
				} else {
					for (const [key, value] of voronoiCells.entries()) {
						if (this.pointsEqual(key, vertex)) {
							value.push({ center, triangle });
							break;
						}
					}
				}
			}
		}
		const voronoiPolygons = [];
		for (const [point, cellData] of voronoiCells.entries()) {
			if (cellData.length < 2) continue;
			
			const centers = cellData.map(d => d.center);
			const cx = centers.reduce((sum, c) => sum + c.x, 0) / centers.length;
			const cy = centers.reduce((sum, c) => sum + c.y, 0) / centers.length;
			
			centers.sort((a, b) => {
				const angleA = Math.atan2(a.y - cy, a.x - cx);
				const angleB = Math.atan2(b.y - cy, b.x - cx);
				return angleA - angleB;
			});
			
			voronoiPolygons.push({
				point: point,
				vertices: centers
			});
		}
		return voronoiPolygons;
	}
}