
export const createHypercubeImgLayer = async (app, points) => {
	await new Promise((resolve, reject) => {
		app.mapboxWrapper.map.loadImage(process.env.PUBLIC_URL + '/static/dataDummyReady/cubeIcon.png', (error, image) => {
			if (error) reject(error);
			if (!app.mapboxWrapper.map.hasImage('packet-icon')) {
				app.mapboxWrapper.map.addImage('packet-icon', image);
			}
			resolve();
		});
	});

	// const points: number[][] = [];

	// geojson.features.forEach((feature: any) => {
	// 	if (feature.geometry.type === 'LineString') {
	// 		points.push(...feature.geometry.coordinates);
	// 	} else if (feature.geometry.type === 'MultiLineString') {
	// 		feature.geometry.coordinates.forEach((lineCoords: number[][]) => {
	// 			points.push(...lineCoords);
	// 		});
	// 	}
	// });

	const pointsGeoJSON = {
		type: 'FeatureCollection',
		features: points.map(coord => ({
			type: 'Feature',
			geometry: {
				type: 'Point',
				coordinates: coord
			},
			properties: {}
		}))
	};

	app.mapboxWrapper.map.addSource('icon-points', {
		type: 'geojson',
		data: pointsGeoJSON
	});

	app.mapboxWrapper.map.addLayer({
		id: 'icon-layer',
		type: 'symbol',
		source: 'icon-points',
		layout: {
			'icon-image': 'packet-icon',
			'icon-size': 0.325,
			'icon-allow-overlap': true
		}
	});
}