import { AppHypercubeMap } from "../AppHypercubeMap";
import { getSlider, getCheckBox } from "../utils/DOMUtils";
export class UI {
	public app: AppHypercubeMap;
	constructor(app: AppHypercubeMap) {
		this.app = app;

	}
	public init(): void {
		const divUIHost = document.createElement('div');
		divUIHost.style.position = 'absolute';
		divUIHost.style.top = '10px';
		divUIHost.style.left = '0px';
		divUIHost.style.padding = '10px';
		divUIHost.style.width = '200px';
		divUIHost.style.height = '95%';
		divUIHost.style.backgroundColor = 'rgba(10, 10, 10, 0.5)';

		const divTitle = document.createElement('div');
		divTitle.style.color = '#fff';
		divTitle.style.fontFamily = 'Arial, sans-serif';
		divTitle.style.fontSize = '16px';
		divTitle.style.fontWeight = 'bold';
		divTitle.style.marginBottom = '10px';
		divTitle.innerText = this.app.config.text.mainTitle;
		divUIHost.appendChild(divTitle);

		//

		const divBtnToggleHypercube = document.createElement('div');
		divBtnToggleHypercube.style.color = '#fff';
		divBtnToggleHypercube.style.fontFamily = 'Arial, sans-serif';
		divBtnToggleHypercube.style.fontSize = '14px';
		divBtnToggleHypercube.style.fontWeight = 'bold';
		divBtnToggleHypercube.style.marginBottom = '10px';
		divBtnToggleHypercube.style.padding = '8px';
		divBtnToggleHypercube.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
		divBtnToggleHypercube.style.borderRadius = '4px';
		divBtnToggleHypercube.style.cursor = 'pointer';
		divBtnToggleHypercube.innerText = 'Hypercube Status';
		divUIHost.appendChild(divBtnToggleHypercube);
		divBtnToggleHypercube.onclick = () => {
			this.app.controller.toggleHypercube();
		};

		const slider = getSlider('Circle Size', 10, 10000)
		divUIHost.appendChild(slider.div);
		slider.div.style.marginBottom = '10px';
		slider.slider.oninput = () => {
			const value = parseFloat(slider.slider.value);
			this.app.controller.setCircleRadius(value);
		};

		const divBtnToggleView = document.createElement('div');
		divBtnToggleView.style.color = '#fff';
		divBtnToggleView.style.fontFamily = 'Arial, sans-serif';
		divBtnToggleView.style.fontSize = '14px';
		divBtnToggleView.style.fontWeight = 'bold';
		divBtnToggleView.style.marginBottom = '10px';
		divBtnToggleView.style.padding = '8px';
		divBtnToggleView.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
		divBtnToggleView.style.borderRadius = '4px';
		divBtnToggleView.style.cursor = 'pointer';
		divBtnToggleView.innerText = 'Toggle View';
		divUIHost.appendChild(divBtnToggleView);
		divBtnToggleView.onclick = () => {
			this.app.controller.toggleView();
		};

		const divBtnToggleMode = document.createElement('div');
		divBtnToggleMode.style.color = '#fff';
		divBtnToggleMode.style.fontFamily = 'Arial, sans-serif';
		divBtnToggleMode.style.fontSize = '14px';
		divBtnToggleMode.style.fontWeight = 'bold';
		divBtnToggleMode.style.marginBottom = '10px';
		divBtnToggleMode.style.padding = '8px';
		divBtnToggleMode.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
		divBtnToggleMode.style.borderRadius = '4px';
		divBtnToggleMode.style.cursor = 'pointer';
		divBtnToggleMode.innerText = 'Day / Night';
		divUIHost.appendChild(divBtnToggleMode);
		divBtnToggleMode.onclick = () => {
			this.app.controller.toggleMode();
		};

		// const divBtnToggleViewAni = document.createElement('div');
		// divBtnToggleViewAni.style.color = '#fff';
		// divBtnToggleViewAni.style.fontFamily = 'Arial, sans-serif';
		// divBtnToggleViewAni.style.fontSize = '14px';
		// divBtnToggleViewAni.style.fontWeight = 'bold';
		// divBtnToggleViewAni.style.marginBottom = '10px';
		// divBtnToggleViewAni.style.padding = '8px';
		// divBtnToggleViewAni.style.backgroundColor = 'rgba(255, 255, 255, 0.2)';
		// divBtnToggleViewAni.style.borderRadius = '4px';
		// divBtnToggleViewAni.style.cursor = 'pointer';
		// divBtnToggleViewAni.innerText = 'Animate camera';
		// divUIHost.appendChild(divBtnToggleViewAni);
		// divBtnToggleViewAni.onclick = () => {
		// 	this.app.controller.animationCamera();
		// };

		const chBoxAAA = getCheckBox('Animation');
		divUIHost.append(chBoxAAA.div);
		chBoxAAA.div.style.marginTop = '10px';
		chBoxAAA.checkBox.onchange = () => {
			// this.app.scene.showDelaunay = chBoxAAA.checkBox.checked;
			this.app.controller.animationCamera();
		}


		const chBoxA = getCheckBox('Show Delaunay');
		divUIHost.append(chBoxA.div);
		chBoxA.div.style.marginTop = '10px';
		chBoxA.checkBox.onchange = () => {
			this.app.scene.showDelaunay = chBoxA.checkBox.checked;
		}

		const chBoxB = getCheckBox('Show Voronoi');
		divUIHost.append(chBoxB.div);
		chBoxB.div.style.marginTop = '10px';
		chBoxB.checkBox.onchange = () => {
			this.app.scene.showVoronoi = chBoxB.checkBox.checked;
		}



		this.app.divHost.appendChild(divUIHost);
	}
	public destroy(): void {
		// TODO
	}
}