import * as THREE from 'three';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';

import { Scene } from '..'
export class Hypercube3D {
	public scene: Scene;

	public BASE_URL = 'https://raw.githubusercontent.com/NamjuLee/data/master/map/';
	private _BASE_URL = 'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/cube/';
	private _BASE_URL_SUB = 'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/fbx/';

	mesh

	constructor(scene: Scene) {
		this.scene = scene;
		this.initPart();
	}

	async initPart() {
		const files = [
			'v91-skin-only.fbx'
			// 'onlyaCube-clean-static-small.fbx',
			// 'onlyaCube-clean-static.fbx',
			// 'onlyaCube-clean-static-noSkin.fbx',
			// "solarPanel.fbx",
			// "door-B-1.fbx",
			// "door-B-2.fbx",
		];
		const scale = 0.001;
		// console.log("1");
		this.mesh = await this.loadAllModels(files, scale);
		this.mesh.rotateY(-90)
		return this.mesh
	}
	private loadAllModels = async (files: string[], scale: number) => {
		try {
			const loadPromises = files.map((file) =>
				loadFBX(this._BASE_URL + file, scale, false, false, [])
			);
			const fbxModels = await Promise.all(loadPromises);
			// console.log(fbxModels)
			// const hypercubeStatic = new HypercubeStatic(this, fbxModels[0]);
			// console.log(hypercubeStatic)
			return fbxModels[0]
		} catch (error) {
			console.error('fail to load :', error);
		}
	};
}



export const loadFBX = (pathFile: string, scale: number = 1, isWebGPU: boolean, performanceMode: boolean = false, clippingPlanes = [], zUp = false): Promise<THREE.Group> => {
	const scaleFactor = scale;
	const usePhysicalMaterial = !performanceMode && !isWebGPU;
	const loader = new FBXLoader();

	return new Promise((resolve, reject) => {
		loader.load(
			pathFile,
			(fbx) => {
				fbx.castShadow = true;
				fbx.receiveShadow = true;

				if (zUp) {
					fbx.rotation.x = Math.PI / 2;
				}

				fbx.traverse((child: THREE.Object3D) => {
					if (isMesh(child)) {
						child.castShadow = true;
						child.receiveShadow = true;

						const material = child.material;

						if (Array.isArray(material)) {
							child.material = material.map((mat) => {
								if (isWebGPU) {
									return new THREE.MeshStandardMaterial({
										map: mat.map ?? undefined,
										color: mat.color ?? new THREE.Color(0xffffff),
										normalMap: mat.normalMap ?? undefined,
										roughness: 0.7,
										metalness: 0.1,
										side: THREE.DoubleSide,
										clippingPlanes: clippingPlanes,
									});
								} else if (performanceMode) {
									return new THREE.MeshStandardMaterial({
										map: mat.map ?? undefined,
										color: mat.color ?? new THREE.Color(0xffffff),
										normalMap: undefined,
										roughness: 0.7,
										metalness: 0.1,
										side: THREE.DoubleSide,
										clippingPlanes: clippingPlanes,
									});
								} else {
									return new THREE.MeshPhysicalMaterial({
										map: mat.map ?? undefined,
										color: mat.color ?? new THREE.Color(0xffffff),
										normalMap: mat.normalMap ?? undefined,
										roughness: 0.7,
										metalness: 0.1,
										side: THREE.DoubleSide,
										clippingPlanes: clippingPlanes,
									});
								}
							});
						} else {
							if (isWebGPU) {
								child.material = new THREE.MeshStandardMaterial({
									map: material.map ?? null,
									color: material.color ?? new THREE.Color(0xffffff),
									normalMap: material.normalMap ?? null,
									roughness: 0.6,
									metalness: 0.2,
									side: THREE.DoubleSide,
									clippingPlanes: clippingPlanes,
								});
							} else if (performanceMode) {
								child.material = new THREE.MeshStandardMaterial({
									map: material.map ?? null,
									color: material.color ?? new THREE.Color(0xffffff),
									roughness: 0.6,
									metalness: 0.2,
									side: THREE.DoubleSide,
									clippingPlanes: clippingPlanes,
								});
							} else {
								child.material = new THREE.MeshPhysicalMaterial({
									map: material.map ?? null,
									color: material.color ?? new THREE.Color(0xffffff),
									normalMap: material.normalMap ?? null,
									roughness: 0.6,
									metalness: 0.2,
									side: THREE.DoubleSide,
									clippingPlanes: clippingPlanes,
								});
							}
						}
					}
				});

				fbx.scale.set(scaleFactor, scaleFactor, scaleFactor);
				fbx.updateMatrixWorld(true);
				resolve(fbx);
			},
			undefined,
			(error) => {
				reject(error);
			}
		);
	});
};
export const isMesh = (obj: THREE.Object3D): obj is THREE.Mesh => {
	return (obj as any).isMesh === true;
};