
export const getSlider = (title: string, min: number, max: number, step: number = 0.1, defaultValue = 1) => {
	const div = document.createElement('div');
	div.style.display = 'flex';
	div.style.flexDirection = 'column';
	div.style.alignItems = 'flex-start';
	div.style.gap = '4px';

	const text = document.createElement('div');
	text.textContent = title;
	text.style.color = '#333';
	text.style.fontSize = '12px';

	const slider = document.createElement('input');
	slider.type = 'range';
	slider.min = `${min}`;
	slider.max = `${max}`;
	slider.step = `${step}`;

	if (defaultValue) {
		slider.defaultValue = `${defaultValue}`;
	}

	slider.style.width = '150px';
	slider.style.height = '4px';
	slider.style.background = 'transparent';
	slider.style.border = 'none';
	slider.style.outline = 'none';
	slider.style.margin = '0';
	slider.style.padding = '0';
	slider.style.webkitAppearance = 'none';
	slider.style.appearance = 'none';
	slider.style.cursor = 'pointer';

	slider.style.setProperty('--track-color', '#aaa');

	const style = document.createElement('style');
	style.textContent = `
	input[type=range]::-webkit-slider-runnable-track {
		height: 4px;
		background: #aaa;
		border-radius: 2px;
	}
	input[type=range]::-webkit-slider-thumb {
		-webkit-appearance: none;
		height: 10px;
		width: 10px;
		border-radius: 50%;
		background: #333;
		margin-top: -3px;
	}
	input[type=range]::-moz-range-track {
		height: 4px;
		background: #333;
		border-radius: 2px;
	}
	input[type=range]::-moz-range-thumb {
		height: 10px;
		width: 10px;
		border-radius: 50%;
		background: #333;
	}
	`;
	document.head.appendChild(style);

	div.appendChild(text);
	div.appendChild(slider);

	return {
		div,
		slider,
		text,
	};
};

export const getCheckBox = (title: string) => {
	const div = document.createElement('div');
	div.style.display = 'flex';

	const checkBox = document.createElement('input');
	checkBox.type = 'checkbox';
	checkBox.defaultChecked = false;
	const text = document.createElement('div');
	text.textContent = title;
	text.style.fontSize = '12px';
	text.style.color = '#aaa';
	div.appendChild(checkBox);
	div.appendChild(text);

	return {
		div,
		checkBox,
	};
};
export const DownloadJSON = (dataJSON: any, fileName: string = 'parametric-hypercube') => {
	const jsonStr = JSON.stringify(dataJSON, null, 2);
	const blob = new Blob([jsonStr], { type: 'application/json' });
	const url = URL.createObjectURL(blob);

	const link = document.createElement('a');
	link.href = url;
	link.download = fileName + '.json';
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
	URL.revokeObjectURL(url);
};
export const getDivider = () => {
	const hr = document.createElement('hr');
	hr.style.border = 'none';
	hr.style.borderTop = '1px solid #000';
	hr.style.margin = '10px 0';
	return hr;
};
